import{_ as e,o as i,c as t,ag as o}from"./chunks/framework.BFM5MFIQ.js";const n="data:image/svg+xml;base64,",m=JSON.parse(`{"title":"Install the app","description":"Install Owlbear's DMH as a standalone app on desktop or mobile.","frontmatter":{"title":"Install the app","description":"Install Owlbear's DMH as a standalone app on desktop or mobile.","order":10},"headers":[],"relativePath":"en/getting-started/install.md","filePath":"en/getting-started/install.md"}`),s={name:"en/getting-started/install.md"};function l(r,a,d,I,g,h){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="install-the-app" tabindex="-1">Install the app <a class="header-anchor" href="#install-the-app" aria-label="Permalink to &quot;Install the app&quot;">​</a></h1><p>Installing Owlbear&#39;s DMH as an app gives it a standalone window and helps the browser treat the campaign data as important.</p><p><img src="'+n+'" alt="The install control in a browser toolbar"></p><h2 id="chrome-and-edge-on-desktop" tabindex="-1">Chrome and Edge on desktop <a class="header-anchor" href="#chrome-and-edge-on-desktop" aria-label="Permalink to &quot;Chrome and Edge on desktop&quot;">​</a></h2><ol><li>Open Owlbear&#39;s DMH in Chrome or Edge.</li><li>Look for the install icon in the address bar. It usually looks like a small monitor with a downward arrow.</li><li>If the icon is not visible, open the browser menu and choose: <ul><li><strong>Chrome:</strong> Cast, save, and share → Install page as app.</li><li><strong>Edge:</strong> Apps → Install this site as an app.</li></ul></li><li>Confirm the installation.</li></ol><h2 id="chrome-and-edge-on-android" tabindex="-1">Chrome and Edge on Android <a class="header-anchor" href="#chrome-and-edge-on-android" aria-label="Permalink to &quot;Chrome and Edge on Android&quot;">​</a></h2><p>Open the browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</p><h2 id="firefox" tabindex="-1">Firefox <a class="header-anchor" href="#firefox" aria-label="Permalink to &quot;Firefox&quot;">​</a></h2><p>Firefox desktop does not provide full PWA installation. Keep the app in a bookmark and use a dedicated window. On Firefox for Android, open the menu and choose <strong>Add to Home screen</strong>.</p><h2 id="safari" tabindex="-1">Safari <a class="header-anchor" href="#safari" aria-label="Permalink to &quot;Safari&quot;">​</a></h2><ul><li><strong>iPhone and iPad:</strong> open the Share menu and choose <strong>Add to Home Screen</strong>.</li><li><strong>macOS:</strong> use <strong>File → Add to Dock</strong> when your Safari version offers it.</li></ul><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><p>Open the app from the system launcher, dock or home screen. Then request persistent storage again from <strong>Settings → Content → Persistent storage</strong>.</p><p>If the browser still refuses, see <a href="./../troubleshooting/persistent-storage.html">Persistent storage</a>.</p>',14)])])}const c=e(s,[["render",l]]);export{m as __pageData,c as default};
